html:
{#- Cover letter and variants of a Sales Proposal, in one document so that the page numbers run through both.
    The letter: the address of the recipient, the date, then the letter. The variants: for each linked quotation that has a variant
    title, its title, two paragraphs, a table of its products (the rows of Variant Products that belong to the quotation) with their
    picture, and its cost simulation. Either part is left out when it is empty.
    A custom format has to add the letterhead and the footer itself, like templates/print_formats/standard.html does. -#}
{% set has_letter = (doc.cover_letter or "") | striptags | trim %}
{% set variants = doc.quotations | selectattr("variant_title") | list %}
<div {% if print_settings.repeat_header_footer %}id="header-html" class="hidden-pdf"{% endif %}>
    {% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
{% if print_settings.repeat_header_footer %}
<div id="footer-html" class="visible-pdf">
    {% if not no_letterhead and footer %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
    <p class="text-center small page-number visible-pdf">
        {{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
    </p>
</div>
{% endif %}

{% if has_letter %}
<div class="bn-letter">
    <div class="bn-letter-address">
        {%- if doc.contact_display %}{{ doc.contact_display }}<br>{% endif -%}
        {%- if doc.address_display %}{{ doc.address_display }}{% else %}{{ doc.customer_name }}{% endif -%}
    </div>
    <div class="bn-letter-date">{{ doc.get_formatted("transaction_date") }}</div>
    <div class="bn-letter-body">{{ doc.cover_letter or "" }}</div>
</div>
{% endif %}

{% for variant in variants %}
{% set items = doc.variant_items | selectattr("quotation", "equalto", variant.quotation) | list %}
<div class="bn-variant{% if has_letter or not loop.first %} bn-variant-next{% endif %}">
    <h1>
        {%- if variants|length > 1 -%}
            {{ _("Variant {0}: {1}").format(loop.index, (variant.variant_title | e)) }}
        {%- else -%}
            {{ variant.variant_title | e }}
        {%- endif -%}
    </h1>
    {% if variant.variant_intro %}<p class="bn-text">{{ variant.variant_intro | e }}</p>{% endif %}
    {% if variant.variant_benefits %}<p class="bn-text">{{ variant.variant_benefits | e }}</p>{% endif %}

    {% if items %}
    <h2 class="bn-heading">{{ _("Solution highlights") }}</h2>
    <table class="bn-variant-items">
        {% for item in items %}
        <tr>
            <td class="bn-variant-image">{% if item.image %}<img src="{{ item.image }}">{% endif %}</td>
            <td class="bn-variant-text">
                <div class="bn-variant-name">{{ (item.item_name or item.item_code) | e }}</div>
                <div class="bn-text bn-variant-description">{{ (item.description or "") | e }}</div>
            </td>
        </tr>
        {% endfor %}
    </table>
    {% endif %}

    {% if variant.cost_simulation %}
    <div class="bn-cost">
        <h2>{{ _("Cost Simulation") }}</h2>
        <div class="bn-cost-body">{{ variant.cost_simulation }}</div>
    </div>
    {% endif %}
</div>
{% endfor %}
<style>    /* bNovate corporate style (Brand Guideline): paragraphs in text grey, blue links and emphasis, light-blue hairline above the footer.
       */
    @font-face { font-family: 'Barlow'; font-weight: 600; src: url('/assets/bnovate/fonts/Barlow-SemiBold.ttf'); }
    @font-face { font-family: 'Barlow'; font-weight: 700; src: url('/assets/bnovate/fonts/Barlow-Bold.ttf'); }
    @font-face { font-family: 'Open Sans'; font-weight: 400; font-style: normal; src: url('/assets/bnovate/fonts/OpenSans-Regular.ttf'); }
    @font-face { font-family: 'Open Sans'; font-weight: 400; font-style: italic; src: url('/assets/bnovate/fonts/OpenSans-Italic.ttf'); }
    @font-face { font-family: 'Open Sans'; font-weight: 600; font-style: normal; src: url('/assets/bnovate/fonts/OpenSans-SemiBold.ttf'); }
    @font-face { font-family: 'Open Sans'; font-weight: 700; font-style: normal; src: url('/assets/bnovate/fonts/OpenSans-Bold.ttf'); }
    .print-format { font-family: 'Open Sans', sans-serif; color: #414141; }
    .bn-letter-body strong, .bn-letter-body b { font-weight: 700; color: #004362; }
    .bn-letter-body a { color: #006996; }
    .letter-head-footer { border-top: 1px solid #8bacc8 !important; padding-top: 2mm; font-size: 7pt; line-height: 1.5; color: #414141; }
    .page-number { color: #8bacc8; }

    /* Wider margins than the rest of our documents, and airy paragraphs */
    .bn-letter { padding: 22mm 16mm 0 16mm; font-size: 10pt; line-height: 1.6; }
    .bn-letter-address { margin: 0 0 12mm 130mm; line-height: 1.4; }  /* right hand window of Swiss envelopes */
    .bn-letter-date { text-align: right; margin-bottom: 14mm; }
    .bn-letter-body p { margin: 0 0 6mm 0; }
    .bn-letter-body ul, .bn-letter-body ol { margin: 0 0 6mm 0; padding-left: 6mm; }

    /* Variants */
    .bn-variant { padding: 16mm 16mm 0 16mm; font-size: 10pt; line-height: 1.6; }
    .bn-variant-next { page-break-before: always; }
    .bn-variant h1 { font-size: 17pt; line-height: 1.25; margin: 0 0 8mm 0; color: #006996; font-family: 'Barlow', sans-serif; font-weight: 600; border-left: 3pt solid #f28f25; padding-left: 4mm; }
    .bn-variant p { margin: 0 0 5mm 0; }
    .bn-text { white-space: pre-line; }  /* the texts are plain text: keep their line breaks */
    .bn-variant-items { width: 100%; border-collapse: collapse; margin-top: 0; }
    .bn-variant-items tr { page-break-inside: avoid; }
    .bn-variant-items td { vertical-align: top; padding: 4mm 0; border-top: 0.5pt solid #d5dde5; }
    .bn-variant-image { width: 36mm; padding-right: 6mm !important; }
    .bn-variant-image img { max-width: 34mm; max-height: 30mm; }
    .bn-variant-name { font-weight: 600; margin-bottom: 1mm; }
    .bn-variant-description { margin-bottom: 2mm; }

    /* Cost simulation. Corporate style: orange kicker like the cover, navy text, hairlines in the grey-blue of the tables.
       The table comes from the Text Editor with its own inline styles, hence the !important. */
    .bn-cost { margin: 8mm 0 0 0; page-break-inside: avoid; }
    /* Section headings: blue Barlow caps (solution highlights, cost simulation) */
    .bn-heading, .bn-cost h2 { font-size: 9pt; line-height: 1.2; font-weight: 700; margin: 0 0 3mm 0; color: #006996; font-family: 'Barlow', sans-serif; text-transform: uppercase; letter-spacing: 0.08em; }
    .bn-heading { margin-top: 8mm; page-break-after: avoid; }
    .bn-cost-body table { width: 100%; border-collapse: collapse; margin: 0 0 3mm 0; font-size: 9.5pt; line-height: 1.45; }
    .bn-cost-body td { padding: 2.2mm 2mm; vertical-align: top; border: 0 !important; border-bottom: 0.5pt solid #d5dde5 !important; }
    .bn-cost-body td:nth-child(n+2) { width: 34mm; text-align: right !important; white-space: nowrap; }
    .bn-cost-body tr:first-child td { padding-top: 0; font-family: 'Barlow', sans-serif; font-size: 8pt; font-weight: 700; color: #004362; text-transform: uppercase; letter-spacing: 0.06em; border-bottom: 1.5pt solid #f28f25 !important; }
    .bn-cost-body tr:last-child td { font-weight: 700; color: #004362; border-top: 1pt solid #004362 !important; border-bottom: 0 !important; }
    .bn-cost-body p { margin: 0 0 3mm 0; }
    .bn-cost-body p:last-child { margin: 0; font-size: 8pt; font-style: italic; color: #414141; }
</style>
